  "recovered_c": "uint64_t fn_18(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len > out_cap) {\n    return 0xFFFFFFFFFFFFFFFF;\n  }\n\n  for (size_t i = 0; i < len; i++) {\n    uint8_t b = in[i];\n    uint64_t state = arg;\n\n    if ((i + 1) * len & 1 || DAT_00104018 != 0) {\n      state = ((len << 7) ^ state) * 0x2d6b + DAT_00104010;\n      state = state >> 0xb ^ state;\n    }\n\n    if (state == 2) {\n      state = 1;\n    } else {\n      if (state == 1) {\n        if (b == 0x5c) {\n          state = 2;\n        } else if (b == 0x22 && ((((i | 1) * (i | 1) & 7) != 1 || DAT_00104010 != 0x3c71)) {\n          state = (uint)arg ^ 0x51e4;\n        }\n      } else {\n        if (b == 0x29) {\n          // Handle closing parenthesis\n        } else if (b < 0x2a) {\n          if (b == 0x22) {\n            i += (int)state;\n            state = i | 1;\n            if (((state * state & 7) == 1) && DAT_00104010 == 0x3c71) {\n              state = 2;\n            } else {\n              state = state + 0x51e3 ^ i * 0x1f9;\n            }\n          } else if (b == 0x28) {\n            // Handle opening parenthesis\n          }\n        } else if (b == 0x7b) {\n          if (state == 0x40) {\n            // Handle opening brace\n          } else {\n            state = state + 0x51e3 ^ len * 0x1f9 + arg;\n          }\n        } else if (b < 0x7c) {\n          if (b == 0x5b) {\n            // Handle opening bracket\n          } else if (b == 0x5d) {\n            // Handle closing bracket\n          }\n        } else if (b == 0x7d) {\n          if ((state == 0) || (state - 1 != b)) {\n            // Handle closing brace\n          } else {\n            state = state + 0x51e3 ^ len * 0x1f9 + arg;\n          }\n        }\n      }\n    }\n\n    out[i] = b;\n  }\n\n  return len;\n}"
